function main({ review_text }) {
  const raw = String(review_text || "").trim();
  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");

  if (start < 0 || end <= start) {
    return {
      decision: "REVISE",
      score: 0,
      revision_instruction: "校验节点未返回可解析的JSON对象，请重新校验并只输出规定JSON。",
      missing_information: "",
      general_feedback: "校验JSON解析失败，禁止猜测PASS。"
    };
  }

  let obj;
  try {
    obj = JSON.parse(raw.slice(start, end + 1));
  } catch (error) {
    return {
      decision: "REVISE",
      score: 0,
      revision_instruction: "校验节点返回的JSON语法无效，请重新校验并输出合法JSON。",
      missing_information: "",
      general_feedback: `校验JSON解析失败：${String(error?.message || error)}`
    };
  }

  const allowed = new Set(["PASS", "REVISE", "STOP_INSUFFICIENT"]);
  const decision = String(obj?.decision || "").trim();
  const normalizedDecision = allowed.has(decision) ? decision : "REVISE";
  const numericScore = Number(obj?.score);
  const score = Number.isFinite(numericScore)
    ? Math.max(0, Math.min(100, Math.round(numericScore)))
    : 0;

  function stringify(value) {
    if (value === undefined || value === null) return "";
    if (typeof value === "string") return value;
    try { return JSON.stringify(value); } catch { return String(value); }
  }

  return {
    decision: normalizedDecision,
    score,
    revision_instruction: normalizedDecision === decision
      ? stringify(obj.revision_instruction)
      : "校验decision字段无效，请重新校验。",
    missing_information: stringify(obj.missing_information),
    general_feedback: normalizedDecision === decision
      ? stringify(obj.general_feedback)
      : "校验decision字段无效，禁止猜测PASS。"
  };
}

