}) {
  const LANE_LIMITS = {
    guideline_a: 6,
    guideline_b: 6,
    clinical_study_initial: 5,
    clinical_study_supplement: 3,
    irae_a: 4,
    irae_b: 4
  };

  const CONTENT_KEYS = new Set([
    "snippet",
    "text",
    "content",
    "pageContent",
